package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
class CashSessionTest extends ApiTestSupport {
 String auth,cash,bank,terminal;UUID branch;
 @BeforeEach void fixture()throws Exception{auth=token(company);branch=db.queryForObject("SELECT id FROM branch WHERE tenant_id=?",UUID.class,tenant);cash=account(branch,"CASH","CASH");bank=account(branch,"BANK","BANK");fund(cash,"100");fund(bank,"200");terminal=createTerminal("T",cash).get("id").asText();}
 String account(UUID branch,String code,String kind)throws Exception{return postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"code",code,"name","Conta "+code,"kind",kind),201).get("id").asText();}
 void fund(String account,String amount)throws Exception{postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"destinationId",account,"amount",amount,"note","Suprimento inicial de teste"),200);}
 Map<String,Object> terminalInput(UUID request,String code,String account){return Map.of("requestId",request,"branchId",branch,"accountId",account,"code",code,"name","Terminal "+code);}
 JsonNode createTerminal(String code,String account)throws Exception{return postApi("/api/v1/pos/terminals",auth,terminalInput(UUID.randomUUID(),code,account),201);}
 Map<String,Object> opening(UUID request,String amount){return Map.of("requestId",request,"terminalId",terminal,"openingAmount",amount,"note","Conferência de abertura");}
 JsonNode open()throws Exception{return postApi("/api/v1/pos/cash-sessions",auth,opening(UUID.randomUUID(),"100"),201);}
 String path(JsonNode s){return "/api/v1/pos/cash-sessions/"+s.get("id").asText();}
 Map<String,Object> move(UUID request,String kind,String amount,String other){var m=new HashMap<String,Object>();m.put("requestId",request);m.put("kind",kind);m.put("amount",amount);m.put("otherAccountId",other);m.put("note","Movimento de caixa de teste");return m;}
 Map<String,Object> close(UUID request,long version,String amount){return Map.of("requestId",request,"version",version,"countedAmount",amount,"note","Contagem física e fechamento");}
 void amount(String expected,JsonNode value){assertEquals(0,new BigDecimal(expected).compareTo(new BigDecimal(value.asText())));assertTrue(value.isTextual());}
 void balance(String account,String expected)throws Exception{amount(expected,getApi("/api/v1/treasury/accounts/"+account,auth,200).get("balance"));}
 long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE tenant_id=?",Long.class,tenant);}
 @Test void terminalCreationIsScopedUniqueIdempotentAndRequiresCashAccount()throws Exception{UUID key=UUID.randomUUID();String other=account(branch,"SECOND","CASH");var input=terminalInput(key,"Second",other);var t=postApi("/api/v1/pos/terminals",auth,input,201);assertEquals(t,postApi("/api/v1/pos/terminals",auth,input,201));var changed=new HashMap<>(input);changed.put("name","Alterado");postApi("/api/v1/pos/terminals",auth,changed,409);postApi("/api/v1/pos/terminals",auth,terminalInput(UUID.randomUUID(),"THIRD",other),409);postApi("/api/v1/pos/terminals",auth,terminalInput(UUID.randomUUID(),"BANK",bank),400);assertEquals(2,count("pos_terminal"));}
 @Test void openingCountMustEqualBalanceAndCannotDuplicateTerminalOrOperator()throws Exception{postApi("/api/v1/pos/cash-sessions",auth,opening(UUID.randomUUID(),"99"),409);UUID key=UUID.randomUUID();var s=postApi("/api/v1/pos/cash-sessions",auth,opening(key,"100"),201);assertEquals(s,postApi("/api/v1/pos/cash-sessions",auth,opening(key,"100.00"),201));postApi("/api/v1/pos/cash-sessions",auth,opening(UUID.randomUUID(),"100"),409);String second=account(branch,"SECOND","CASH");terminal=createTerminal("SECOND",second).get("id").asText();postApi("/api/v1/pos/cash-sessions",auth,opening(UUID.randomUUID(),"0"),409);balance(cash,"100");assertEquals(1,count("pos_cash_session"));}
 @Test void cashMovementsAndTransfersAreAtomicIdempotentAndIncreaseVersion()throws Exception{var s=open();UUID key=UUID.randomUUID();var body=move(key,"SUPPLY","50",bank);var m=postApi(path(s)+"/movements",auth,body,200);assertEquals(m,postApi(path(s)+"/movements",auth,move(key,"SUPPLY","50.00",bank),200));balance(cash,"150");balance(bank,"150");postApi(path(s)+"/movements",auth,move(UUID.randomUUID(),"WITHDRAW","30",bank),200);balance(cash,"120");balance(bank,"180");var current=getApi(path(s),auth,200);assertEquals(2,current.get("version").asInt());amount("120",current.get("expectedAmount"));assertEquals(2,getApi(path(s)+"/movements",auth,200).get("total").asInt());postApi(path(s)+"/movements",auth,move(key,"SUPPLY","51",bank),409);}
 @Test void insufficientFundsOrSameAccountRollBackBothLedgers()throws Exception{var s=open();postApi(path(s)+"/movements",auth,move(UUID.randomUUID(),"WITHDRAW","101",bank),409);postApi(path(s)+"/movements",auth,move(UUID.randomUUID(),"SUPPLY","201",bank),409);postApi(path(s)+"/movements",auth,move(UUID.randomUUID(),"SUPPLY","1",cash),400);assertEquals(0,count("pos_cash_movement"));assertEquals(2,count("treasury_operation"));balance(cash,"100");}
 @Test void closeRecordsDifferenceWithoutAdjustingTreasuryAndReplayNeverReopens()throws Exception{UUID openingKey=UUID.randomUUID();var s=postApi("/api/v1/pos/cash-sessions",auth,opening(openingKey,"100"),201);UUID closeKey=UUID.randomUUID();var body=close(closeKey,0,"95");var closed=postApi(path(s)+"/close",auth,body,200);assertEquals("CLOSED",closed.get("status").asText());amount("-5",closed.get("difference"));amount("100",closed.get("expectedAmount"));balance(cash,"100");assertEquals(closed,postApi(path(s)+"/close",auth,body,200));assertEquals(closed,postApi("/api/v1/pos/cash-sessions",auth,opening(openingKey,"100"),201));postApi(path(s)+"/movements",auth,move(UUID.randomUUID(),"SUPPLY","1",null),409);fund(cash,"5");amount("100",getApi(path(s),auth,200).get("expectedAmount"));amount("-5",getApi(path(s),auth,200).get("difference"));}
 @Test void closedSessionReleasesOperatorAndAccountForNewShift()throws Exception{var s=open();postApi(path(s)+"/close",auth,close(UUID.randomUUID(),0,"100"),200);var next=open();assertNotEquals(s.get("id").asText(),next.get("id").asText());assertEquals(2,count("pos_cash_session"));}
 @Test void externalTreasuryAndFinanceCannotWriteReservedDrawer()throws Exception{var s=open();postApi("/api/v1/treasury/movements",auth,Map.of("requestId",UUID.randomUUID(),"destinationId",cash,"amount","1","note","Fora do caixa aberto"),409);var customer=postApi("/api/v1/customers",auth,Map.of("code","C","name","Cliente","taxIdentifier","","contactName","","email","","phone","","address","","notes",""),201);var t=postApi("/api/v1/receivables",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"customerId",customer.get("id").asText(),"reference","IN","document","","description","Título de teste","issuedOn","2020-01-01","dueOn","2020-02-01","amount","10"),201);postApi("/api/v1/receivables/"+t.get("id").asText()+"/receipts",auth,Map.of("receiptId",UUID.randomUUID(),"amount","1","receivedOn","2020-02-01","method","CASH","reference","","note","Recebimento de teste","treasuryAccountId",cash),409);assertEquals(0,count("receivable_receipt"));balance(cash,"100");}
 @Test void onlyOwnerOrExplicitSupervisorMayOperateOrClose()throws Exception{var s=open();var user=postApi("/api/v1/users",auth,Map.of("name","Operador","email","operator@example.com","password",password,"permissions",List.of("pos:read","pos:operate","pos:close","treasury:read","treasury:move")),201);String other=postApi("/api/v1/auth/login",null,Map.of("company",company,"email","operator@example.com","password",password),200).get("token").asText();postApi(path(s)+"/movements",other,move(UUID.randomUUID(),"SUPPLY","1",null),403);postApi(path(s)+"/close",other,close(UUID.randomUUID(),0,"100"),403);db.update("INSERT INTO user_permission(tenant_id,user_id,permission) VALUES(?,?,'pos:supervise')",tenant,UUID.fromString(user.get("id").asText()));postApi(path(s)+"/close",other,close(UUID.randomUUID(),0,"100"),200);}
 @Test void inactiveTerminalAndStaleCloseAreRejected()throws Exception{var s=open();http.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put("/api/v1/pos/terminals/"+terminal+"/active").header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(Map.of("active",false,"version",0)))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isConflict());postApi(path(s)+"/movements",auth,move(UUID.randomUUID(),"SUPPLY","1",null),200);postApi(path(s)+"/close",auth,close(UUID.randomUUID(),0,"101"),409);postApi(path(s)+"/close",auth,close(UUID.randomUUID(),1,"101"),200);db.update("UPDATE pos_terminal SET active=FALSE WHERE tenant_id=? AND id=?",tenant,UUID.fromString(terminal));postApi("/api/v1/pos/cash-sessions",auth,opening(UUID.randomUUID(),"101"),409);}
 @Test void movementReplayAfterCloseDoesNotRepostCash()throws Exception{var s=open();var body=move(UUID.randomUUID(),"SUPPLY","10",null);var original=postApi(path(s)+"/movements",auth,body,200);postApi(path(s)+"/close",auth,close(UUID.randomUUID(),1,"110"),200);assertEquals(original,postApi(path(s)+"/movements",auth,body,200));balance(cash,"110");assertEquals(1,count("pos_cash_movement"));}
 @Test void tenantAndBranchScopeCoverTerminalSessionAndHistory()throws Exception{var s=open();String other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);getApi(path(s),token(other),404);UUID user=db.queryForObject("SELECT id FROM app_user WHERE tenant_id=?",UUID.class,tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE id=?",user);assertEquals(0,getApi("/api/v1/pos/terminals",auth,200).get("total").asInt());assertEquals(0,getApi("/api/v1/pos/cash-sessions",auth,200).get("total").asInt());getApi(path(s),auth,404);getApi(path(s)+"/movements",auth,404);postApi(path(s)+"/close",auth,close(UUID.randomUUID(),0,"100"),404);}
 @Test void openingAndClosingPermissionAreIndependent()throws Exception{db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='pos:close'",tenant);var s=open();postApi(path(s)+"/close",auth,close(UUID.randomUUID(),0,"100"),403);db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission='treasury:move'",tenant);postApi(path(s)+"/movements",auth,move(UUID.randomUUID(),"SUPPLY","1",null),403);getApi(path(s),auth,200);}
 @Test void concurrentOpeningAndWithdrawalHaveSingleEffects()throws Exception{var input=opening(UUID.randomUUID(),"100");assertEquals(List.of(201,201),concurrent("/api/v1/pos/cash-sessions",input,"/api/v1/pos/cash-sessions",input));var s=getApi("/api/v1/pos/cash-sessions",auth,200).get("items").get(0);assertEquals(List.of(200,409),concurrent(path(s)+"/movements",move(UUID.randomUUID(),"WITHDRAW","80",null),path(s)+"/movements",move(UUID.randomUUID(),"WITHDRAW","80",null)));balance(cash,"20");assertEquals(1,count("pos_cash_movement"));}
 @Test void closingRaceWithMovementPreservesCountAndVersion()throws Exception{var s=open();var result=concurrent(path(s)+"/close",close(UUID.randomUUID(),0,"100"),path(s)+"/movements",move(UUID.randomUUID(),"SUPPLY","1",null));assertEquals(List.of(200,409),result);var current=getApi(path(s),auth,200);if(current.get("status").asText().equals("CLOSED")){amount("100",current.get("expectedAmount"));balance(cash,"100");}else{assertEquals(1,current.get("version").asInt());balance(cash,"101");}}
 @Test void transferReplayRevalidatesCounterpartBranchScope()throws Exception{var s=open();UUID otherBranch=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","OTHER","name","Outra"),201).get("id").asText());String other=account(otherBranch,"OTHER","BANK");fund(other,"50");var command=move(UUID.randomUUID(),"SUPPLY","10",other);postApi(path(s)+"/movements",auth,command,200);UUID user=db.queryForObject("SELECT id FROM app_user WHERE tenant_id=?",UUID.class,tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE id=?",user);db.update("INSERT INTO user_branch_access(tenant_id,user_id,branch_id) VALUES(?,?,?)",tenant,user,branch);postApi(path(s)+"/movements",auth,command,404);balance(cash,"110");assertEquals(1,count("pos_cash_movement"));}
 List<Integer> concurrent(String p1,Object b1,String p2,Object b2)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();return status(p1,b1);});var b=pool.submit(()->{gate.await();return status(p2,b2);});gate.countDown();var result=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(result);return result;}}
 int status(String path,Object body)throws Exception{return http.perform(post(path).header("Authorization","Bearer "+auth).contentType("application/json").content(json.writeValueAsString(body))).andReturn().getResponse().getStatus();}
}
